// Short AI clips for the Video page. Muse has no video model (docs/muse-api.md), so each clip is
// made from Muse-generated stills: the video's keyframes (src/shared/seed/videos.json `frames`,
// generated by `npm run gen:images`) get slow camera moves and crossfades; a video without
// keyframes gets one move over its poster (the 1600 px original from .cache/images when there).
// Output: public/seed/videos/<key>.mp4, 960x540, about 0.5 MB, no audio. Needs ffmpeg on PATH.
// Existing clips are kept; pass --force to rebuild them all, or --only=key1,key2.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

const ROOT = join(import.meta.dirname, "..");
const PUB = join(ROOT, "public");
const VIDEOS = JSON.parse(readFileSync(join(ROOT, "src", "shared", "seed", "videos.json"), "utf8"));
const MODEL = process.env.MUSE_MODEL_IMAGE || "muse-image-1.0";
// Must match the poster prompt in scripts/gen-images.mjs, so the cached original is found.
const NO_TEXT = "No text overlays, no captions, no logos, no brand names, no readable signs, no recognizable real storefronts or landmarks.";
const posterPrompt = (v) => `Realistic still frame from a casual phone video posted on social media: ${v.poster}. Natural light, candid, ordinary fictional people if any. ${NO_TEXT}`;

const FPS = 30;
const SHOT = 3;        // seconds per keyframe
const FADE = 0.6;      // crossfade
const SOLO = 6;        // seconds for a poster-only clip
const force = process.argv.includes("--force");
const only = process.argv.find((a) => a.startsWith("--only="))?.slice(7).split(",");

/** A slow move: zoom in, zoom out, or pan; varied per shot so cuts feel alive. */
function move(i, d) {
  const n = d * FPS;
  const moves = [
    `zoompan=z='1+0.12*on/${n}':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)'`,
    `zoompan=z='1.12':x='(iw-iw/zoom)*on/${n}':y='ih/2-(ih/zoom/2)'`,
    `zoompan=z='1.14-0.12*on/${n}':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)'`,
    `zoompan=z='1.12':x='(iw-iw/zoom)*(1-on/${n})':y='ih/2-(ih/zoom/2)'`,
  ];
  return `scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,${moves[i % moves.length]}:d=${n}:s=960x540:fps=${FPS},setsar=1`;
}

let made = 0;
for (const [vi, v] of VIDEOS.entries()) {
  if (only && !only.includes(v.key)) continue;
  const out = join(PUB, "seed", "videos", `${v.key}.mp4`);
  if (existsSync(out) && !force) continue;
  let inputs;
  if (v.frames?.length) {
    inputs = v.frames.map((_, i) => join(PUB, "seed", "videos", "frames", `${v.key}-${i + 1}.webp`));
  } else {
    const cached = join(ROOT, ".cache", "images", `${createHash("sha256").update(MODEL + "\n" + posterPrompt(v)).digest("hex")}.webp`);
    inputs = [existsSync(cached) ? cached : join(PUB, "seed", "videos", `${v.key}.webp`)];
  }
  const missing = inputs.filter((p) => !existsSync(p));
  if (missing.length) { console.warn(`skip ${v.key}: missing ${missing.join(", ")} (run npm run gen:images)`); continue; }

  const args = ["-hide_banner", "-loglevel", "error", "-y"];
  inputs.forEach((p) => args.push("-i", p));
  let filter;
  if (inputs.length === 1) {
    filter = `[0:v]${move(vi, SOLO)},format=yuv420p[out]`;
  } else {
    const parts = inputs.map((_, i) => `[${i}:v]${move(vi + i, SHOT)}[s${i}]`);
    let prev = "s0";
    for (let i = 1; i < inputs.length; i++) {
      const tag = i === inputs.length - 1 ? "x" : `x${i}`;
      parts.push(`[${prev}][s${i}]xfade=transition=fade:duration=${FADE}:offset=${(i * (SHOT - FADE)).toFixed(2)}[${tag}]`);
      prev = tag;
    }
    parts.push(`[x]format=yuv420p[out]`);
    filter = parts.join(";");
  }
  args.push("-filter_complex", filter, "-map", "[out]", "-an", "-c:v", "libx264", "-preset", "slow", "-crf", "27", "-movflags", "+faststart", out);
  execFileSync("ffmpeg", args, { stdio: "inherit" });
  made++;
  console.log(`clip ${v.key}: ${inputs.length} frame(s), ${(statSync(out).size / 1024).toFixed(0)} KB`);
}
console.log(`made ${made} clip(s)`);
